import sys

class TreeNode:
    def __init__(self, val=0):
        self.val = val
        self.left = None
        self.right = None

def insert(root, val):
    if root is None:
        return TreeNode(val)
    if val < root.val:
        root.left = insert(root.left, val)
    else:
        root.right = insert(root.right, val)
    return root

def find_inorder_successor(root, k):
    successor = None
    current = root

    while current is not None:
        if k < current.val:
            successor = current
            current = current.left
        elif k > current.val:
            current = current.right
        else:
            if current.right is not None:
                current = current.right
                while current.left is not None:
                    current = current.left
                successor = current
            break

    return successor

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    values = list(map(int, data[1:1+n]))
    k = int(data[1+n])

    root = None
    for val in values:
        root = insert(root, val)

    result = find_inorder_successor(root, k)

    if result:
        print(result.val)
    else:
        print("null")

if __name__ == "__main__":
    main()
